// Club calendar. One-off events come from calendar.json (migrated from the Wix calendar, 21 November 2026).
// The weekly timetable comes from the owner-confirmed sessions in @tti/domain.
// The public feed for calendar apps is /leeside-calendar.ics, generated by scripts/build-calendar.mjs.
import { leesideSessions } from "@tti/domain";
import data from "./calendar.json";

export type CalendarEvent = {
  id: string;
  title: string;
  /** Dublin wall-clock start, e.g. 2025-09-01T18:00 */
  start: string;
  end: string | null;
  timezone: "Europe/Dublin";
  startUtc: string;
  endUtc: string | null;
  venue: string | null;
  address: string | null;
  cancelled: boolean;
  description: string | null;
  source: string | null;
};

export const CALENDAR_EVENTS = data.events as CalendarEvent[];
export const CALENDAR_FEED = "/leeside-calendar.ics";
export const SEASON_START = data.seasonStart;

/** Events that have not been cancelled and start after `now`, soonest first. */
export function upcomingEvents(now: number): CalendarEvent[] {
  return CALENDAR_EVENTS.filter((e) => !e.cancelled && Date.parse(e.startUtc) > now).sort(
    (a, b) => Date.parse(a.startUtc) - Date.parse(b.startUtc),
  );
}

const DAY_INDEX: Record<string, number> = { Sunday: 0, Monday: 1, Tuesday: 2, Wednesday: 3, Thursday: 4, Friday: 5, Saturday: 6 };

const addDays = (iso: string, days: number) => {
  const d = new Date(`${iso}T12:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
};

/** Weekly timetable expanded into dated occurrences from `from` up to and including `to` (YYYY-MM-DD). */
export function weeklyOccurrences(from: string, to: string) {
  const out: { id: string; title: string; start: string; end: string; venue: string; audience: string }[] = [];
  for (const s of leesideSessions) {
    const [startHm, endHm] = s.time.split(/[–-]/).map((t) => t.trim().padStart(5, "0"));
    let date = from;
    while (new Date(`${date}T12:00:00Z`).getUTCDay() !== DAY_INDEX[s.day]) date = addDays(date, 1);
    for (; date <= to; date = addDays(date, 7)) {
      out.push({
        id: `${s.id}-${date}`,
        title: s.title,
        start: `${date}T${startHm}`,
        end: `${date}T${endHm}`,
        venue: s.venue,
        audience: s.audience,
      });
    }
  }
  return out;
}
